-- Data titik koordinat per-assignment (peta sebaran titik SLS)
-- Diekspor: 2026-09-28 dari DB se2026 lokal.
--
-- Portabel: TIDAK mengandalkan sls.id lokal — kode_sls yang dipakai untuk
-- me-resolve sls_id, jadi aman kalau id SLS di server berbeda. Jalankan
-- db/assignment_koordinat_migration.sql dulu (bikin tabel assignment_koordinat),
-- lalu file ini.
--
-- Sumber asli: FASIH Dashboard SQL Lab, base_table_assignment.
-- Kalau nanti mau refresh, cukup jalankan scraper/sync_usaha.py (FASE 3) di
-- server — file ini cuma buat seed/import cepat sekali jalan.

CREATE TABLE IF NOT EXISTS assignment_koordinat (
    id            INT NOT NULL AUTO_INCREMENT,
    assignment_id VARCHAR(64) NOT NULL,
    sls_id        INT DEFAULT NULL,
    latitude      DECIMAL(11,7) NOT NULL,
    longitude     DECIMAL(11,7) NOT NULL,
    updated_at    DATETIME DEFAULT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_ak_assignment (assignment_id),
    KEY idx_ak_sls (sls_id),
    CONSTRAINT fk_ak_sls FOREIGN KEY (sls_id) REFERENCES sls (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS assignment_koordinat_staging;
CREATE TABLE assignment_koordinat_staging (
    assignment_id VARCHAR(64) NOT NULL,
    kode_sls      VARCHAR(20) NOT NULL,
    latitude      DECIMAL(11,7) NOT NULL,
    longitude     DECIMAL(11,7) NOT NULL,
    updated_at    DATETIME DEFAULT NULL,
    KEY idx_aks_kode (kode_sls)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Pindahkan ke tabel tujuan, resolve sls_id dari kode_sls.
SELECT st.assignment_id, s.id, st.latitude, st.longitude, st.updated_at
FROM assignment_koordinat_staging st
JOIN sls s ON s.kode_sls = st.kode_sls
ON DUPLICATE KEY UPDATE
    sls_id     = VALUES(sls_id),
    latitude   = VALUES(latitude),
    longitude  = VALUES(longitude),
    updated_at = VALUES(updated_at);

DROP TABLE assignment_koordinat_staging;

SELECT COUNT(*) AS total_assignment_koordinat FROM assignment_koordinat;
